"""Offline Batch5 review using the established Batch1/2/3/4 gallery interface."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parent
assets=json.loads((ROOT/'manifest.json').read_text())['assets']
descriptions={
'A':'An old concrete irrigation passage beneath the Park, with water pipes, a closed maintenance door and a sealed industrial locker at the far end.',
'B':'A formal personnel exit with a small closed wall-mounted first-aid box, botanical-exposure pictogram and old lid seal.',
'C':'A separately generated closer view of the same irrigation door and tall decontamination locker. Both remain closed.',
'D':'The initial cargo inspection checkpoint: sealed certified cargo, idle scanner/press/plate, shipment gate and a closed treatment dispenser in its own wall alcove.',
'E':'The shared public-concourse destination: a quiet intact bay of the approved Exposition architecture, without the tram, collision or branch-specific evidence.'}
comparisons=[('service-route-continuity','Approved Waste Chute → new Lower Irrigation → new Maintenance Exit'),('underground-material-continuity','Approved underground station → new irrigation passage'),('closed-treatment-containers','Compact public box → tall industrial locker → Customs alcove dispenser'),('public-route-continuity','Approved Control Tower → new public-side exit → new concourse'),('customs-material-continuity','Approved administrative machinery → new cargo checkpoint'),('concourse-architecture-continuity','Approved concourse crash location → new quiet intact concourse bay')]
def fig(stem,title,cls=''):
 return f'<figure class="{cls}"><div class="scroll"><img class="pixel scaled" data-stem="{stem}" src="previews/{stem}-native.png" alt="{escape(title)}"></div><figcaption>{escape(title)}</figcaption></figure>'
cards=[]
for a in assets:
 k=a['id'];stem=Path(a['candidatePath']).stem;title=a['registryKey'].split('/')[-1].replace('_',' ').title()
 cards.append(f'<article class="asset" id="asset-{k}"><header><div class="eyebrow">{k} / RGB 314×206 / generated, unselected</div><h3>{title}</h3><div class="id"><code>{a["registryKey"]}</code></div><p>{descriptions[k]}</p></header>'+fig(stem,title)+f'<div class="asset-links"><a href="{a["candidatePath"]}">Native game candidate</a><a href="previews/{stem}-4x.png">Exact 4× preview</a><a href="{a["source"]}">Original detailed source</a><a href="prompts/{k}-v01.txt">Exact prompt</a></div></article>')
docs=[('README.md','Batch5 handoff','Source pins, native file contract and reproducible workflow'),('BATCH4_APPROVAL.md','Batch4 final approval','Six selected hashes; all91 public images verified'),('CANDIDATE_HASHES.md','Five candidate paths and hashes','Exact PNG mappings and SHA-256 values'),('ARTWORK_CONTINUITY_REVIEW.md','Visual review','Native clarity, shared fixtures and limits'),('STORY_CONTINUITY.md','Canonical story context','Initial states and later branch/Focus distinctions'),('VISUAL_DIRECTION.md','Visual direction','Approved steel/teal world and distinct room functions'),('qa.json','Pixel QA','Dimensions, opacity, palette and exact4× verification'),('manifest.json','Candidate manifest','Generated statuses, provenance and normalization metrics'),('generation-records.json','Generation provenance','Exact prompts, source paths and reference roles'),('SOURCE_SHA256SUMS.txt','Source hashes','Original renders, references and canonical snapshots'),('REMAINING_QUEUE.md','Remaining Chapter2 artwork','18 records; inventory, Focus and death briefs unchanged'),('build_review.py','Deterministic processing','Whole-canvas native exports; no local repainting'),('STORYBOARD_SYNC.md','Publication receipt','Canonical status update and Pages result')]
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Biology Park · Batch5 · Review</title><link rel="stylesheet" href="gallery.css"></head><body><header><div class="eyebrow">The Acceptable Error / Chapter2 / Batch5 / November17,2026</div><h1>Irrigation and exits.<br><span style="color:#b9c9b1">Five distinct places to leave the Park.</span></h1><p><span class="status">Five generated candidates · Art Director review pending</span></p><p class="muted">Batch4 is finally owner-approved and registered. All91 selected public-art hashes have been verified. These five new candidates remain generated and unselected; all prior approved pixels are unchanged.</p><nav aria-label="Review sections"><a href="#scenes">Five scenes</a><a href="#continuity">Continuity comparisons</a><a href="#evidence">QA and sources</a></nav></header><div class="toolbar"><div class="toolbar-inner"><div class="button-group" role="group" aria-label="Preview scale"><span class="group-label">View</span><button type="button" data-scale="1" aria-pressed="true">Native314×206</button><button type="button" data-scale="4" aria-pressed="false">Exact4×</button></div><span class="muted" style="font-size:12px">Nearest-neighbor PNGs · full-size images scroll · no fractional scaling</span></div></div><main><section id="scenes"><div class="eyebrow">A–E / actual generated artwork</div><h2>Five irrigation and exit environments</h2><p class="note">Every game candidate is opaque RGB314×206 using the existing64-color palette. Every enlarged scene preview is exact1256×824. Detailed generation sources are preserved separately. The three treatment containers remain closed; their later Focus A contents are not part of these main scenes.</p>'''
html+=fig('five-scenes','Lower Irrigation · Public Exit · Maintenance Exit · Agricultural Customs · Exposition Concourse')+''.join(cards)
html+='</section><section id="continuity"><div class="eyebrow">Approved references / distinct functions</div><h2>Inspect continuity at native pixels</h2><p>The service passage and its closer exit share the same door/locker. Public, maintenance and cargo exits retain distinct architecture and treatment containers. The new concourse is a quiet intact bay, not an edit or repair of the approved crash illustration.</p>'
html+=''.join(fig(s,t,'comparison') for s,t in comparisons)
html+='</section><section id="evidence"><div class="eyebrow">Evidence / provenance / handoff</div><h2>Review findings and technical checks</h2><figure><div class="scroll"><img class="pixel" src="previews/palette.png" alt="Exact existing owner-selected64-color palette"></div><figcaption>No dithering, crop, padding or local pixel repainting. Source signage already uses pictograms and deliberate graphic rules. Native texture metrics do not establish creative approval.</figcaption></figure><div class="docs">'
html+=''.join(f'<a class="doc" href="{p}"><strong>{title}</strong><span>{detail}</span></a>' for p,title,detail in docs)
html+='''</div><p>Gameplay handoff: use the native PNGs and integer nearest-neighbor display with smoothing disabled. No production paths or gameplay integration are assigned. Inventory/Focus dimensions, death-screen records and authored story content remain unchanged.</p></section></main><footer>Five genuine built-in image-generation candidates · generated, not selected · original sources and previous approved art preserved.</footer><script>'use strict';function setScale(scale){document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===scale)));document.querySelectorAll('.scaled').forEach(img=>{img.removeAttribute('width');img.removeAttribute('height');img.src='previews/'+img.dataset.stem+(scale===4?'-4x.png':'-native.png');});}document.querySelectorAll('[data-scale]').forEach(b=>b.addEventListener('click',()=>setScale(Number(b.dataset.scale))));</script></body></html>'''
(ROOT/'index.html').write_text(html)
print('Offline gallery built:five scenes,six comparisons,native/exact4x controls.')
